CREATE TABLE `pacientes` (`id_paciente` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL COMMENT 'Nombre completo', `correo` VARCHAR(160) NOT NULL, `ciudad` VARCHAR(90), `fecha_registro` DATE NOT NULL, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_paciente`)) ENGINE=InnoDB COMMENT='Personas registradas';
CREATE TABLE `especialidades` (`id_especialidad` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(100) NOT NULL, `descripcion` VARCHAR(180), PRIMARY KEY (`id_especialidad`)) ENGINE=InnoDB COMMENT='Clasificación de recursos';
CREATE TABLE `servicios_medicos` (`id_servicio_medico` INT NOT NULL AUTO_INCREMENT, `id_especialidad` INT NOT NULL, `nombre` VARCHAR(130) NOT NULL, `tarifa` DECIMAL(11,2) NOT NULL, `capacidad_diaria` INT NOT NULL DEFAULT 0, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_servicio_medico`), KEY `idx_recurso_categoria` (`id_especialidad`), CONSTRAINT `fk_recurso_categoria` FOREIGN KEY (`id_especialidad`) REFERENCES `especialidades` (`id_especialidad`)) ENGINE=InnoDB COMMENT='Recursos o artículos del catálogo';
CREATE TABLE `sedes_clinicas` (`id_sede_clinica` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL, `ciudad` VARCHAR(90) NOT NULL, `fecha_apertura` DATE, PRIMARY KEY (`id_sede_clinica`)) ENGINE=InnoDB COMMENT='Ubicaciones operativas';
CREATE TABLE `medicos` (`id_medico` INT NOT NULL AUTO_INCREMENT, `id_sede_clinica` INT NOT NULL, `nombre` VARCHAR(110) NOT NULL, `salario` DECIMAL(11,2), `fecha_ingreso` DATE, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_medico`), KEY `idx_empleado_sede` (`id_sede_clinica`), CONSTRAINT `fk_empleado_sede` FOREIGN KEY (`id_sede_clinica`) REFERENCES `sedes_clinicas` (`id_sede_clinica`)) ENGINE=InnoDB COMMENT='Personal';
CREATE TABLE `atenciones` (`id_atencion` INT NOT NULL AUTO_INCREMENT, `id_paciente` INT NOT NULL, `id_medico` INT NOT NULL, `id_sede_clinica` INT NOT NULL, `fecha` DATE NOT NULL, `estado` VARCHAR(25) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `comentario` VARCHAR(180), PRIMARY KEY (`id_atencion`), KEY `idx_operacion_persona` (`id_paciente`), KEY `idx_operacion_empleado` (`id_medico`), KEY `idx_operacion_sede` (`id_sede_clinica`), CONSTRAINT `fk_operacion_persona` FOREIGN KEY (`id_paciente`) REFERENCES `pacientes` (`id_paciente`), CONSTRAINT `fk_operacion_empleado` FOREIGN KEY (`id_medico`) REFERENCES `medicos` (`id_medico`), CONSTRAINT `fk_operacion_sede` FOREIGN KEY (`id_sede_clinica`) REFERENCES `sedes_clinicas` (`id_sede_clinica`)) ENGINE=InnoDB COMMENT='Registro principal de operaciones';
CREATE TABLE `procedimientos_atencion` (`id_procedimiento_atencion` INT NOT NULL AUTO_INCREMENT, `id_atencion` INT NOT NULL, `id_servicio_medico` INT NOT NULL, `cantidad` INT NOT NULL, `precio_unitario` DECIMAL(11,2) NOT NULL, `descuento` DECIMAL(10,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id_procedimiento_atencion`), KEY `idx_detalle_operacion` (`id_atencion`), KEY `idx_detalle_recurso` (`id_servicio_medico`), CONSTRAINT `fk_detalle_operacion` FOREIGN KEY (`id_atencion`) REFERENCES `atenciones` (`id_atencion`), CONSTRAINT `fk_detalle_recurso` FOREIGN KEY (`id_servicio_medico`) REFERENCES `servicios_medicos` (`id_servicio_medico`)) ENGINE=InnoDB COMMENT='Detalle de recursos por operación';
CREATE TABLE `pagos_atencion` (`id_pago_atencion` INT NOT NULL AUTO_INCREMENT, `id_atencion` INT NOT NULL, `fecha_pago` DATE NOT NULL, `monto` DECIMAL(12,2) NOT NULL, `metodo` VARCHAR(25) NOT NULL, `confirmado` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_pago_atencion`), KEY `idx_pago_operacion` (`id_atencion`), CONSTRAINT `fk_pago_operacion` FOREIGN KEY (`id_atencion`) REFERENCES `atenciones` (`id_atencion`)) ENGINE=InnoDB COMMENT='Movimientos de cobro';
CREATE TABLE `seguimientos` (`id_seguimiento` INT NOT NULL AUTO_INCREMENT, `id_atencion` INT NOT NULL, `fecha_evento` DATE NOT NULL, `tipo` VARCHAR(50) NOT NULL, `descripcion` VARCHAR(220), `puntuacion` INT, PRIMARY KEY (`id_seguimiento`), KEY `idx_evento_operacion` (`id_atencion`), CONSTRAINT `fk_evento_operacion` FOREIGN KEY (`id_atencion`) REFERENCES `atenciones` (`id_atencion`)) ENGINE=InnoDB COMMENT='Eventos de seguimiento asociados a una operación';
